import"chrome://resources/ash/common/cr_elements/cr_button/cr_button.js";import"./help_content.js";import"./help_resources_icons.html.js";import"./os_feedback_shared.css.js";import{I18nMixin}from"chrome://resources/ash/common/cr_elements/i18n_mixin.js";import{strictQuery}from"chrome://resources/ash/common/typescript_utils/strict_query.js";import{stringToMojoString16}from"chrome://resources/js/mojo_type_util.js";import{PolymerElement}from"chrome://resources/polymer/v3_0/polymer/polymer_bundled.min.js";import{btRegEx,buildWordMatcher,FeedbackFlowState}from"./feedback_flow.js";import{showScrollingEffectOnStart,showScrollingEffects}from"./feedback_utils.js";import{getHelpContentProvider}from"./mojo_interface_provider.js";import{domainQuestions,questionnaireBegin}from"./questionnaire.js";import{getTemplate}from"./search_page.html.js";const MAX_RESULTS=5;export const OS_FEEDBACK_UNTRUSTED_ORIGIN="chrome-untrusted://os-feedback";const wifiRegEx=buildWordMatcher(["wifi","wi-fi","internet","network","hotspot"]);const cellularRegEx=buildWordMatcher(["2G","3G","4G","5G","LTE","UMTS","SIM","eSIM","mmWave","mobile","APN","IMEI","IMSI","eUICC","carrier","T.Mobile","TMO","Verizon","VZW","AT&T","MVNO","pin.lock","cellular"]);const displayRegEx=buildWordMatcher(["display","displayport","hdmi","monitor","panel","screen"]);const usbRegEx=buildWordMatcher(["USB","USB-C","Type-C","TypeC","USBC","USBTypeC","USBPD","hub","charger","dock"]);const thunderboltRegEx=buildWordMatcher(["Thunderbolt","Thunderbolt3","Thunderbolt4","TBT","TBT3","TBT4","TB3","TB4"]);const SearchPageElementBase=I18nMixin(PolymerElement);export class SearchPageElement extends SearchPageElementBase{static get is(){return"search-page"}static get template(){return getTemplate()}static get properties(){return{feedbackContext:{type:Object,readOnly:false,notify:true},descriptionTemplate:{type:String,readonly:true,observer:SearchPageElement.prototype.descriptionTemplateChanged},descriptionPlaceholderText:{type:String,readonly:true,observer:SearchPageElement.prototype.descriptionPlaceholderTextChanged},helpContentSearchResultCount:{type:Number,notify:true},noHelpContentDisplayed:{type:Boolean,notify:true}}}constructor(){super();this.descriptionTemplate="";this.descriptionPlaceholderText="";this.helpContentSearchResultCount=0;this.noHelpContentDisplayed=false;this.appendedQuestions=[];this.isPopularContentForTesting=false;this.searchTimerID=-1;this.querySeqNo=0;this.searchTimoutInMs=250;this.helpContentProvider=getHelpContentProvider();this.lastPostedQuerySeqNo=-1;this.iframeLoaded=new Promise((resolve=>{this.resolveIframeLoaded=resolve}));this.iframeLoaded.then((()=>{this.focusInputElement();showScrollingEffectOnStart(this)}))}ready(){super.ready();this.iframe=strictQuery("iframe",this.shadowRoot,HTMLIFrameElement);this.fetchHelpContent("",this.getNextQuerySeqNo());this.getInputElement().addEventListener("input",(()=>this.checkForShowQuestionnaire()));window.addEventListener("message",(e=>{const message=e.data;if(message.iframeHeight){this.style.setProperty("--iframe-height",message.iframeHeight.toString()+"px")}}),false)}handleInputChanged(e){clearTimeout(this.searchTimerID);const textArea=e.target;const query=textArea.value.trim();if(query.length>0){this.hideError()}if(!this.isUserLoggedIn()){return}const querySeqNo=this.getNextQuerySeqNo();this.searchTimerID=setTimeout((()=>{this.fetchHelpContent(query,querySeqNo)}),this.searchTimoutInMs)}getNextQuerySeqNo(){return this.querySeqNo++}isUserLoggedIn(){return this.feedbackContext?.categoryTag!=="Login"}async fetchHelpContent(query,querySeqNo){if(!this.iframe){console.warn("untrusted iframe is not found");return}if(!this.isUserLoggedIn()){return}const request={query:stringToMojoString16(query),maxResults:MAX_RESULTS};const isQueryEmpty=query==="";let isPopularContent;let response;if(isQueryEmpty){if(this.popularHelpContentList===undefined){response=await this.helpContentProvider.getHelpContents(request);this.popularHelpContentList=response.response.results}this.helpContentSearchResultCount=this.popularHelpContentList.length;isPopularContent=true}else{response=await this.helpContentProvider.getHelpContents(request);isPopularContent=response.response.results.length===0;this.helpContentSearchResultCount=response.response.results.length}this.isPopularContentForTesting=isPopularContent;const data={contentList:isPopularContent?this.popularHelpContentList:response.response.results,isQueryEmpty:isQueryEmpty,isPopularContent:isPopularContent};this.noHelpContentDisplayed=data.contentList.length===0;await this.iframeLoaded;if(querySeqNo>this.lastPostedQuerySeqNo){this.lastPostedQuerySeqNo=querySeqNo;this.iframe.contentWindow.postMessage(data,OS_FEEDBACK_UNTRUSTED_ORIGIN)}}getInputElement(){return strictQuery("#descriptionText",this.shadowRoot,HTMLTextAreaElement)}focusInputElement(){this.getInputElement().focus()}onInputInvalid(){this.showError();this.focusInputElement()}getErrorElement(){return strictQuery("#emptyErrorContainer",this.shadowRoot,HTMLElement)}showError(){const errorElement=this.getErrorElement();errorElement.hidden=false;errorElement.setAttribute("aria-hidden","false");const descriptionTextElement=this.getInputElement();descriptionTextElement.classList.add("has-error")}hideError(){const errorElement=this.getErrorElement();if(errorElement.hidden){return}errorElement.hidden=true;errorElement.setAttribute("aria-hidden","true");const descriptionTextElement=this.getInputElement();descriptionTextElement.classList.remove("has-error")}feedbackWritingGuidanceUrl(){const url="https://support.google.com/chromebook/answer/2982029";return url}handleContinueButtonClicked(e){e.stopPropagation();const textInput=this.getInputElement().value.trim();if(textInput.length===0){this.onInputInvalid()}else{this.dispatchEvent(new CustomEvent("continue-click",{composed:true,bubbles:true,detail:{currentState:FeedbackFlowState.SEARCH,description:textInput}}))}}setDescription(text){this.getInputElement().value=text}descriptionTemplateChanged(currentTemplate){this.getInputElement().value=currentTemplate}descriptionPlaceholderTextChanged(currentPlaceholder){if(currentPlaceholder===""){this.getInputElement().placeholder=this.i18n("descriptionHint")}else{this.getInputElement().placeholder=currentPlaceholder}}checkForShowQuestionnaire(){if(!this.feedbackContext.isInternalAccount){return}const toAppend=[];const textarea=this.getInputElement();const value=textarea.value;const questionnaireBeginPos=value.indexOf(questionnaireBegin);const matchedText=questionnaireBeginPos>=0?value.substring(0,questionnaireBeginPos):value;if(btRegEx.test(matchedText)){toAppend.push(...domainQuestions["bluetooth"])}if(wifiRegEx.test(matchedText)){toAppend.push(...domainQuestions["wifi"])}if(cellularRegEx.test(matchedText)){toAppend.push(...domainQuestions["cellular"])}if(displayRegEx.test(matchedText)){toAppend.push(...domainQuestions["display"])}if(thunderboltRegEx.test(matchedText)){toAppend.push(...domainQuestions["thunderbolt"])}else if(usbRegEx.test(matchedText)){toAppend.push(...domainQuestions["usb"])}if(toAppend.length===0){return}const savedCursor=textarea.selectionStart;if(this.appendedQuestions.length===0){textarea.value+="\n\n"+questionnaireBegin+"\n"}for(const question of toAppend){if(this.appendedQuestions.includes(question)){continue}textarea.value+="* "+question+" \n";this.appendedQuestions.push(question)}textarea.selectionEnd=savedCursor}onContainerScroll(event){showScrollingEffects(event,this)}getSearchResultCountForTesting(){return this.helpContentSearchResultCount}getIsPopularContentForTesting(){return this.isPopularContentForTesting}getNextQuerySeqNoForTesting(){return this.querySeqNo}setNextQuerySeqNoForTesting(nextQuerySeqNo){this.querySeqNo=nextQuerySeqNo}getLastPostedQuerySeqNoForTesting(){return this.lastPostedQuerySeqNo}}customElements.define(SearchPageElement.is,SearchPageElement);